// Every fact the property page shows in more than one place.
//
// The public design deliberately repeats itself: the rent appears in the hero
// and again inside each unit panel, the bedroom count appears in the hero, on
// the card and in the search filters, availability appears as an eyebrow, a
// badge and a per-unit line. That repetition is good design and a bad schema —
// if each surface reads its own field, somebody has to remember to change the
// price in three places, and the day they forget the page contradicts itself.
//
// So the rule is: a unit owns its own facts, and everything the property shows
// above the units is DERIVED from them. This file owns every one of those
// derivations, which is what makes them testable and what stops the rules
// drifting into JSX in five different components.
//
// Each function falls back to the property-level field when a property has no
// units at all — a single house is a property with no unit types, not a broken
// one — so the twelve bundled listings keep rendering exactly as they do now.

import type { FloorPlan, FloorPlanAvailability } from "../floor-plans/types";
import type { GalleryImage } from "../gallery/types";
import type { Property, PropertyRecord } from "./types";

/** Either shape works: none of these rules touch the resolved photograph. */
type AnyProperty = Partial<Property> & Partial<PropertyRecord>;

const plansOf = (property: AnyProperty): FloorPlan[] =>
  Array.isArray(property.floorPlans) ? property.floorPlans : [];

/* ── publication ───────────────────────── */

/**
 * Whether this listing is on the website at all.
 *
 * Deliberately NOT the same question as availability, and the two are easy to
 * confuse because both sound like "is this live":
 *
 *   publication   is this listing on the website?
 *   availability  can somebody move into it?
 *
 * They are independent. A published property may say "Contact for
 * Availability" and still have a page, a card and a place in search — that is
 * an ordinary listing for a building with a waiting list. A draft property is
 * not public even when it says "Available Now", because nobody has finished
 * writing it yet.
 *
 * Absent means published, which is what keeps the twelve bundled listings —
 * none of which carries the field — behaving exactly as they always have.
 */
export function isPublished(property: AnyProperty): boolean {
  /* Two independent reasons to withhold a property, and the second one is the
     trap: a property moved to the Trash keeps whatever publication state it
     had, so checking `publication` alone would leave a deleted listing on the
     website with a page, a search result and a place in Similar Properties.
     Deleted beats published. */
  if (property.deletedAt) return false;

  return property.publication !== "draft";
}

/**
 * The listings the public site may show.
 *
 * Since MTC-KRP-036 that also excludes anything in the Trash; see isPublished.
 *
 * Every public surface funnels through this: the pages that get built, the
 * search results, Featured Properties and Similar Properties. One function
 * rather than four `filter` calls, because the day somebody adds a fifth
 * surface the question is "did you use publishedOnly" rather than "did you
 * remember the rule".
 */
export function publishedOnly<T extends AnyProperty>(properties: T[]): T[] {
  return properties.filter(isPublished);
}

/* ── price ───────────────────────────────────────────────── */

/**
 * Pricing, as one value with two legitimate shapes.
 *
 * `rentFrom: number | null` already meant this, and the null case already meant
 * "contact for pricing" — but the hero dropped the whole line for null while
 * the floor-plan panel printed "Contact for pricing" for the same state. A
 * union makes the contact case something a renderer has to handle rather than
 * something it can quietly skip.
 */
export type Price =
  | { kind: "monthly"; amount: number }
  | { kind: "contact" };

const monthly = (amount: unknown): Price | null =>
  typeof amount === "number" && Number.isFinite(amount) && amount > 0
    ? { kind: "monthly", amount }
    : null;

/**
 * What the page shows above the units: the cheapest thing you can actually
 * rent.
 *
 * Units that are unavailable are excluded — advertising "from $995" for
 * something nobody can move into is the kind of thing a client hears about.
 * Falls back to the property's own figure when there are no units, and to
 * "contact" rather than inventing zero.
 */
export function startingPrice(property: AnyProperty): Price {
  const rentable = plansOf(property)
    .filter((plan) => plan.availability !== "unavailable")
    .map((plan) => monthly(plan.rentFrom))
    .filter((price): price is { kind: "monthly"; amount: number } => price !== null);

  if (rentable.length > 0) {
    return rentable.reduce((low, price) => (price.amount < low.amount ? price : low));
  }

  return monthly(property.rentFrom) ?? monthly(property.rent) ?? { kind: "contact" };
}

/* ── availability ────────────────────────────────────────── */

/**
 * Whether anything here can be moved into.
 *
 * Ranked rather than counted: one available unit makes the property available,
 * because that is what a visitor is asking. Only when nothing is available does
 * the weaker state surface.
 */
const RANK: Record<FloorPlanAvailability, number> = {
  available: 3,
  limited: 2,
  contact: 1,
  unavailable: 0,
};

export function availabilityOf(property: AnyProperty): FloorPlanAvailability {
  const plans = plansOf(property);

  if (plans.length > 0) {
    return plans.reduce<FloorPlanAvailability>(
      (best, plan) => (RANK[plan.availability] > RANK[best] ? plan.availability : best),
      "unavailable"
    );
  }

  /* No units: read the property's own free-text field. Matched loosely because
     it is authored prose — "Available Now", "Available Soon" — not an enum. */
  const text = (property.availability ?? "").trim();
  if (!text) return "contact";
  /* Before the rest, and deliberately. "Unavailable" contains "available",
     so any test for that word matches it first and a property marked as not
     available would read as available - the exact opposite of what was
     chosen. */
  if (/unavailab|not available|sold/i.test(text)) return "unavailable";
  if (/now|immediate/i.test(text)) return "available";
  if (/limited|few/i.test(text)) return "limited";
  if (/soon|from/i.test(text)) return "limited";
  return "contact";
}

/** True only when something is genuinely available, for the hero's eyebrow. */
export function isAvailable(property: AnyProperty): boolean {
  return availabilityOf(property) === "available";
}

/* ── bedrooms, bathrooms, area ───────────────────────────── */

export type Range = { min: number; max: number };

function rangeOf(values: number[]): Range | null {
  const usable = values.filter((value) => Number.isFinite(value) && value >= 0);
  if (usable.length === 0) return null;
  return { min: Math.min(...usable), max: Math.max(...usable) };
}

export function bedroomRange(property: AnyProperty): Range | null {
  const plans = plansOf(property);
  if (plans.length > 0) return rangeOf(plans.map((plan) => plan.bedrooms));
  return rangeOf([property.bedrooms as number]);
}

export function bathroomRange(property: AnyProperty): Range | null {
  const plans = plansOf(property);
  if (plans.length > 0) return rangeOf(plans.map((plan) => plan.bathrooms));
  return rangeOf([property.bathrooms as number]);
}

export function areaRange(property: AnyProperty): Range | null {
  const plans = plansOf(property);
  if (plans.length > 0) return rangeOf(plans.map((plan) => plan.squareFeet));
  return rangeOf([property.area as number]);
}

export type RoomLabels = {
  studio: string;
  bed: string;
  beds: string;
  bath: string;
  baths: string;
};

export const defaultRoomLabels: RoomLabels = {
  studio: "Studio",
  bed: "Bed",
  beds: "Beds",
  bath: "Bath",
  baths: "Baths",
};

export function bedroomLabel(count: number, labels = defaultRoomLabels): string {
  if (!Number.isFinite(count) || count < 0) return "";
  if (count === 0) return labels.studio;
  return `${count} ${count === 1 ? labels.bed : labels.beds}`;
}

export function bathroomLabel(count: number, labels = defaultRoomLabels): string {
  if (!Number.isFinite(count) || count <= 0) return "";
  return `${count} ${count === 1 ? labels.bath : labels.baths}`;
}

/**
 * "1 Bed", or "Studio–2 Beds" when the units differ.
 *
 * A building offering a studio through a two-bed cannot honestly print a single
 * number at the top of the page, which is what it does today by reading one
 * property-level field.
 */
export function bedroomSummary(property: AnyProperty, labels = defaultRoomLabels): string {
  const range = bedroomRange(property);
  if (!range) return "";
  if (range.min === range.max) return bedroomLabel(range.min, labels);

  const low = range.min === 0 ? labels.studio : String(range.min);
  return `${low}–${bedroomLabel(range.max, labels)}`;
}

/* ── images ──────────────────────────────────────────────── */

export function imagesOf(property: AnyProperty): GalleryImage[] {
  return Array.isArray(property.images) ? property.images : [];
}

/** Images for a given surface. `roles` is what lets one asset serve several. */
export function imagesForRole(property: AnyProperty, role: string): GalleryImage[] {
  return imagesOf(property).filter((image) => image.roles?.includes(role));
}

/**
 * How many photographs the gallery will actually show.
 *
 * Counted, not typed. The record carried a hand-entered `photoCount` that
 * nothing verified — several listings claimed eighteen photographs while the
 * gallery rendered eight — so the hero's "View 18 Photos" was a promise the
 * next click broke.
 */
export function photoCount(property: AnyProperty): number {
  const gallery = imagesForRole(property, "gallery");
  return gallery.length > 0 ? gallery.length : imagesOf(property).length;
}

/**
 * The one photograph that represents this property.
 *
 * A role rather than a field, which is MTC-KRP-024's answer to the "large
 * image and small image" pair the planning notes asked for: those were one
 * asset described twice, and the second description was always the one that
 * went stale. As a role it cannot outlive the photograph it points at, and the
 * renderer stays free to crop it differently in the hero than in the overview.
 *
 * Falls back to the first photograph, which is what the page already does for
 * a property nobody has ranked — so choosing none is a valid state rather than
 * a broken one.
 */
export function featuredImage(property: AnyProperty): GalleryImage | null {
  const chosen = imagesForRole(property, "featured");
  return chosen[0] ?? imagesOf(property)[0] ?? null;
}

/**
 * The gallery's filter chips.
 *
 * Only categories some image actually has, in first-seen order. An image with
 * no category still appears under All — it is simply not reachable from a chip,
 * which is the right outcome: "No category" is an authoring state, not a thing
 * a visitor should be asked to filter by.
 */
export function galleryCategories(images: GalleryImage[]): string[] {
  const seen: string[] = [];
  for (const image of images) {
    const category = image.category?.trim();
    if (category && !seen.includes(category)) seen.push(category);
  }
  return seen;
}

/* ── similar properties ──────────────────────────────────── */

/**
 * Applies an author's manual adjustments to an automatic ordering.
 *
 * Pinned slugs come first in the order given; excluded slugs never appear. The
 * automatic result fills whatever is left, so a property with no manual
 * adjustment behaves exactly as it does today.
 *
 * Slugs rather than copies: pinning a property must not embed a snapshot of it
 * that goes stale the moment its rent changes.
 */
export function applySimilarOverrides<T extends { slug: string }>(
  automatic: T[],
  all: T[],
  refs: { pinned?: string[]; excluded?: string[] } | undefined,
  limit: number
): T[] {
  const excluded = new Set(refs?.excluded ?? []);
  const pinnedSlugs = (refs?.pinned ?? []).filter((slug) => !excluded.has(slug));

  const bySlug = new Map(all.map((item) => [item.slug, item]));
  const pinned = pinnedSlugs
    .map((slug) => bySlug.get(slug))
    .filter((item): item is T => Boolean(item));

  const taken = new Set(pinned.map((item) => item.slug));

  const rest = automatic.filter(
    (item) => !taken.has(item.slug) && !excluded.has(item.slug)
  );

  return [...pinned, ...rest].slice(0, limit);
}
