import React, { useMemo, useState } from "react";
import { Link } from "gatsby";
import { LuBedDouble, LuBath, LuLayoutGrid, LuList, LuRuler, LuSearch, LuSlidersHorizontal, LuX } from "react-icons/lu";

import { availabilityOf, publishedOnly, startingPrice } from "../ppm/modules/property/derive";
import type { Property } from "../ppm/modules/property/types";
import { resolveProperty } from "../ppm/primitives/property/property-images";
import { useCatalogue } from "../ppm/primitives/property/useCatalogue";
import { Btn } from "./Chrome";

const dollars = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });
const compact = (n: number) => (n >= 1_000_000 ? `$${n / 1_000_000}M` : `$${n / 1000}K`);
export const num = new Intl.NumberFormat("en-US");

/** `rent` holds the list price on this site; see primitives/property/property-data.ts. */
export function priceOf(property: Property): number | null {
  const price = startingPrice(property);
  return price.kind === "monthly" ? price.amount : null;
}
export function priceLabel(property: Property): string {
  const price = priceOf(property);
  return price === null ? "Contact for price" : dollars.format(price);
}

/** Bundled demo records are the only ones with ids starting "sbs-". */
export const isSample = (property: Property) => property.id.startsWith("sbs-");
export const townOf = (property: Property) => property.location.split(",")[0].trim();

/** Every published listing, with its photograph resolved. */
export function useListings(): Property[] {
  const { data } = useCatalogue();
  return useMemo(() => publishedOnly(data).map(resolveProperty), [data]);
}

export function Facts({ property }: { property: Property }) {
  return (
    <ul className="sbs-facts">
      <li>
        <LuBedDouble size={16} aria-hidden="true" /> <b>{property.bedrooms}</b> bed
      </li>
      <li>
        <LuBath size={16} aria-hidden="true" /> <b>{property.bathrooms}</b> bath
      </li>
      <li>
        <LuRuler size={16} aria-hidden="true" /> <b>{num.format(property.area)}</b> sqft
      </li>
    </ul>
  );
}

export function ListingCard({ property, wide }: { property: Property; wide?: boolean }) {
  const state = availabilityOf(property);
  return (
    <Link to={`/properties/${property.slug}/`} className={`sbs-listing${wide ? " sbs-listing--wide" : ""}`}>
      <div className="sbs-listing__img">
        {property.image ? (
          <img src={property.image} srcSet={property.imageSrcSet} sizes="(max-width: 620px) 100vw, 33vw" alt={property.imageAlt} loading="lazy" />
        ) : null}
        {property.availability ? (
          <span className={`sbs-chip${state === "available" ? " sbs-chip--gold" : ""}`}>{property.availability}</span>
        ) : null}
        {isSample(property) ? <span className="sbs-chip sbs-chip--sample">Sample listing</span> : null}
      </div>
      <div className="sbs-listing__body">
        <p className="sbs-price">{priceLabel(property)}</p>
        <h3 className="sbs-card-title">{property.title}</h3>
        <p className="sbs-listing__loc">
          {property.location} · {property.type}
        </p>
        {wide && property.summary ? <p className="sbs-listing__sum">{property.summary}</p> : null}
        <Facts property={property} />
      </div>
    </Link>
  );
}

export function ListingGrid({ listings }: { listings: Property[] }) {
  return (
    <div className="sbs-grid">
      {listings.map((property) => (
        <ListingCard key={property.slug} property={property} />
      ))}
    </div>
  );
}

type Filters = {
  q: string;
  towns: string[];
  types: string[];
  status: string[];
  feats: string[];
  beds: number;
  baths: number;
  min: number;
  max: number;
};
const EMPTY: Filters = { q: "", towns: [], types: [], status: [], feats: [], beds: 0, baths: 0, min: 0, max: 0 };
const PRICE_STEPS = [250000, 400000, 500000, 600000, 750000, 1000000, 1500000, 2000000];

const toggle = (list: string[], value: string) => (list.includes(value) ? list.filter((v) => v !== value) : [...list, value]);

function Check({ label, count, on, onChange }: { label: string; count?: number; on: boolean; onChange: () => void }) {
  return (
    <label className="sbs-check">
      <input type="checkbox" checked={on} onChange={onChange} />
      <span>{label}</span>
      {count !== undefined ? <em>{count}</em> : null}
    </label>
  );
}

function Pills({ value, onChange, options }: { value: number; onChange: (n: number) => void; options: number[] }) {
  return (
    <div className="sbs-pills">
      {[0, ...options].map((n) => (
        <button key={n} type="button" className={n === value ? "is-on" : undefined} onClick={() => onChange(n)}>
          {n === 0 ? "Any" : `${n}+`}
        </button>
      ))}
    </div>
  );
}

/** The /properties page: sidebar filters, active chips, sort, grid/list. */
export function ListingsPage({ search }: { search: string }) {
  const all = useListings();
  const [f, setF] = useState<Filters>(() => {
    const params = new URLSearchParams(search);
    const town = params.get("town");
    const type = params.get("type");
    return {
      ...EMPTY,
      q: params.get("q") ?? "",
      towns: town ? [town] : [],
      types: type ? [type] : [],
      max: Number(params.get("max")) || 0,
      beds: Number(params.get("beds")) || 0,
    };
  });
  const [sort, setSort] = useState("featured");
  const [view, setView] = useState<"grid" | "list">("grid");
  const [drawer, setDrawer] = useState(false);
  const set = (patch: Partial<Filters>) => setF((current) => ({ ...current, ...patch }));

  const options = useMemo(() => {
    const tally = (pick: (p: Property) => string[]) => {
      const map = new Map<string, number>();
      all.forEach((p) => pick(p).forEach((v) => map.set(v, (map.get(v) ?? 0) + 1)));
      return Array.from(map.entries()).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    };
    return {
      towns: tally((p) => [townOf(p)]),
      types: tally((p) => [p.type]),
      status: tally((p) => (p.availability ? [p.availability] : [])),
      feats: tally((p) => p.amenities ?? []).slice(0, 10),
    };
  }, [all]);

  const shown = useMemo(() => {
    const needle = f.q.trim().toLowerCase();
    const list = all.filter((p) => {
      const price = priceOf(p);
      return (
        (!needle || `${p.title} ${p.location} ${p.type} ${(p.amenities ?? []).join(" ")}`.toLowerCase().includes(needle)) &&
        (!f.towns.length || f.towns.includes(townOf(p))) &&
        (!f.types.length || f.types.includes(p.type)) &&
        (!f.status.length || (p.availability && f.status.includes(p.availability))) &&
        (!f.feats.length || f.feats.every((x) => (p.amenities ?? []).includes(x))) &&
        (!f.beds || p.bedrooms >= f.beds) &&
        (!f.baths || p.bathrooms >= f.baths) &&
        (!f.min || (price !== null && price >= f.min)) &&
        (!f.max || (price !== null && price <= f.max))
      );
    });
    const price = (p: Property) => priceOf(p) ?? Number.MAX_SAFE_INTEGER;
    if (sort === "low") list.sort((a, b) => price(a) - price(b));
    if (sort === "high") list.sort((a, b) => price(b) - price(a));
    if (sort === "new") list.sort((a, b) => (b.listedOn ?? "").localeCompare(a.listedOn ?? ""));
    if (sort === "size") list.sort((a, b) => b.area - a.area);
    if (sort === "featured") list.sort((a, b) => Number(!!b.featured) - Number(!!a.featured));
    return list;
  }, [all, f, sort]);

  const chips: { label: string; clear: () => void }[] = [
    ...(f.q.trim() ? [{ label: `“${f.q.trim()}”`, clear: () => set({ q: "" }) }] : []),
    ...f.towns.map((v) => ({ label: v, clear: () => set({ towns: toggle(f.towns, v) }) })),
    ...f.types.map((v) => ({ label: v, clear: () => set({ types: toggle(f.types, v) }) })),
    ...f.status.map((v) => ({ label: v, clear: () => set({ status: toggle(f.status, v) }) })),
    ...f.feats.map((v) => ({ label: v, clear: () => set({ feats: toggle(f.feats, v) }) })),
    ...(f.beds ? [{ label: `${f.beds}+ beds`, clear: () => set({ beds: 0 }) }] : []),
    ...(f.baths ? [{ label: `${f.baths}+ baths`, clear: () => set({ baths: 0 }) }] : []),
    ...(f.min ? [{ label: `From ${compact(f.min)}`, clear: () => set({ min: 0 }) }] : []),
    ...(f.max ? [{ label: `Up to ${compact(f.max)}`, clear: () => set({ max: 0 }) }] : []),
  ];

  const sidebar = (
    <aside className={`sbs-side-filters${drawer ? " is-open" : ""}`} aria-label="Filters">
      <div className="sbs-side-filters__head">
        <h2 className="sbs-card-title">Filters</h2>
        <button type="button" className="sbs-link" onClick={() => setF(EMPTY)}>
          Clear all
        </button>
        <button type="button" className="sbs-side-filters__close" onClick={() => setDrawer(false)} aria-label="Close filters">
          <LuX size={22} />
        </button>
      </div>

      <fieldset>
        <legend>Location</legend>
        {options.towns.map(([v, n]) => (
          <Check key={v} label={v} count={n} on={f.towns.includes(v)} onChange={() => set({ towns: toggle(f.towns, v) })} />
        ))}
      </fieldset>
      <fieldset>
        <legend>Home type</legend>
        {options.types.map(([v, n]) => (
          <Check key={v} label={v} count={n} on={f.types.includes(v)} onChange={() => set({ types: toggle(f.types, v) })} />
        ))}
      </fieldset>
      <fieldset>
        <legend>Bedrooms</legend>
        <Pills value={f.beds} onChange={(beds) => set({ beds })} options={[1, 2, 3, 4, 5]} />
      </fieldset>
      <fieldset>
        <legend>Bathrooms</legend>
        <Pills value={f.baths} onChange={(baths) => set({ baths })} options={[1, 2, 3, 4]} />
      </fieldset>
      <fieldset>
        <legend>Price</legend>
        <div className="sbs-range">
          <select value={f.min} onChange={(e) => set({ min: Number(e.target.value) })} aria-label="Minimum price">
            <option value={0}>No min</option>
            {PRICE_STEPS.map((n) => (
              <option key={n} value={n}>
                {compact(n)}
              </option>
            ))}
          </select>
          <span>–</span>
          <select value={f.max} onChange={(e) => set({ max: Number(e.target.value) })} aria-label="Maximum price">
            <option value={0}>No max</option>
            {PRICE_STEPS.map((n) => (
              <option key={n} value={n}>
                {compact(n)}
              </option>
            ))}
          </select>
        </div>
      </fieldset>
      {options.status.length > 1 ? (
        <fieldset>
          <legend>Status</legend>
          {options.status.map(([v, n]) => (
            <Check key={v} label={v} count={n} on={f.status.includes(v)} onChange={() => set({ status: toggle(f.status, v) })} />
          ))}
        </fieldset>
      ) : null}
      <fieldset>
        <legend>Features</legend>
        {options.feats.map(([v, n]) => (
          <Check key={v} label={v} count={n} on={f.feats.includes(v)} onChange={() => set({ feats: toggle(f.feats, v) })} />
        ))}
      </fieldset>
      <button type="button" className="sbs-btn sbs-side-filters__apply" onClick={() => setDrawer(false)}>
        Show {shown.length} {shown.length === 1 ? "home" : "homes"}
      </button>
    </aside>
  );

  return (
    <>
      <section className="sbs-pagehead">
        <div className="sbs-wrap">
          <span className="sbs-eyebrow">Listings</span>
          <h1 className="sbs-title">Homes across the Treasure Valley</h1>
          <label className="sbs-search">
            <LuSearch size={20} aria-hidden="true" />
            <input type="search" value={f.q} onChange={(e) => set({ q: e.target.value })} placeholder="Search by town, home name or feature" aria-label="Search listings" />
          </label>
        </div>
      </section>

      <section className="sbs-section" style={{ paddingTop: 40 }}>
        <div className="sbs-wrap sbs-lst">
          {sidebar}
          {drawer ? <div className="sbs-scrim" onClick={() => setDrawer(false)} /> : null}

          <div>
            <div className="sbs-toolbar">
              <p>
                <b>{shown.length}</b> {shown.length === 1 ? "home" : "homes"}
              </p>
              <button type="button" className="sbs-btn sbs-btn--ghost sbs-toolbar__filters" onClick={() => setDrawer(true)}>
                <LuSlidersHorizontal size={16} /> Filters{chips.length ? ` (${chips.length})` : ""}
              </button>
              <select value={sort} onChange={(e) => setSort(e.target.value)} aria-label="Sort">
                <option value="featured">Featured first</option>
                <option value="new">Newest</option>
                <option value="low">Price: low to high</option>
                <option value="high">Price: high to low</option>
                <option value="size">Largest first</option>
              </select>
              <div className="sbs-viewtoggle" role="group" aria-label="View">
                <button type="button" className={view === "grid" ? "is-on" : undefined} onClick={() => setView("grid")} aria-label="Grid view">
                  <LuLayoutGrid size={18} />
                </button>
                <button type="button" className={view === "list" ? "is-on" : undefined} onClick={() => setView("list")} aria-label="List view">
                  <LuList size={18} />
                </button>
              </div>
            </div>

            {chips.length ? (
              <div className="sbs-chips">
                {chips.map((chip) => (
                  <button key={chip.label} type="button" onClick={chip.clear}>
                    {chip.label} <LuX size={14} aria-hidden="true" />
                  </button>
                ))}
                <button type="button" className="sbs-link" onClick={() => setF(EMPTY)}>
                  Clear all
                </button>
              </div>
            ) : null}

            {shown.length ? (
              <div className={view === "list" ? "sbs-list" : "sbs-grid sbs-grid--2"}>
                {shown.map((property) => (
                  <ListingCard key={property.slug} property={property} wide={view === "list"} />
                ))}
              </div>
            ) : (
              <div className="sbs-empty">
                <p>No homes match those filters. Try widening them, or ask Sajra about off-market options.</p>
                <Btn to="/contact/">Contact Sajra</Btn>
              </div>
            )}
          </div>
        </div>
      </section>
    </>
  );
}
